import{_ as n,a0 as o,w as m,s as p,I as e,x as a,a1 as i,A as s,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"KDE Plasma 5.23 的新功能和發佈日期 | LCTT x X-CMD","titleTemplate":false,"description":"KDE Plasma 5.23 的新功能和發佈日期 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"KDE Plasma 5.23 的新功能和發佈日期 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"KDE Plasma 5.23 的新功能和發佈日期 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210823 KDE Plasma 5.23 - New Features and Release Dates","title":"KDE Plasma 5.23 的新功能和發佈日期","tag":"202108","desc":""},"relativePath":"202108/20210823 KDE Plasma 5.23 - New Features and Release Dates.md","filePath":"[post].md"}'),d={name:"202108/20210823 KDE Plasma 5.23 - New Features and Release Dates.md"};function u(f,l,w,D,P,K){const t=o("Link");return m(),p("div",null,[l[19]||(l[19]=e("h1",{id:"kde-plasma-5-23-的新功能和發佈日期",tabindex:"-1"},[a("KDE Plasma 5.23 的新功能和發佈日期 "),e("a",{class:"header-anchor",href:"#kde-plasma-5-23-的新功能和發佈日期","aria-label":"Permalink to “KDE Plasma 5.23 的新功能和發佈日期”"},"​")],-1)),l[20]||(l[20]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/25/222802zwhmvv1vwzusevzw.jpg",alt:""})],-1)),l[21]||(l[21]=e("blockquote",null,[e("p",null,"我們在這篇文章中總結了 KDE Plasma 5.23（即將到來）的新功能，包括主要特點、下載和 測試説明。")],-1)),e("p",null,[l[1]||(l[1]=a("KDE Plasma 桌面是當今最流行、最頂級的 Linux 桌面環境，而 KDE Plasma 的熱度之高主要得益於其適應能力強、迭代發展迅速，以及性能不斷提高。",-1)),i(t,{href:"https://www.debugpoint.com/2021/06/kde-plasma-5-22-release/"},{default:s(()=>[...l[0]||(l[0]=[a("KDE Plasma 5.22",-1)])]),_:1}),l[2]||(l[2]=a(" 發佈以來，KDE 團隊一直忙於為即將到來的 KDE Plasma 5.23 合併更改和測試新功能。目前 KDE Plasma 5.23 仍在開發中，如下是暫定的時間表。",-1))]),l[22]||(l[22]=r('<h3 id="kde-plasma-5-23-發佈時間表" tabindex="-1">KDE Plasma 5.23 發佈時間表 <a class="header-anchor" href="#kde-plasma-5-23-發佈時間表" aria-label="Permalink to “KDE Plasma 5.23 發佈時間表”">​</a></h3><p>KDE Plasma 5.23 將於 2021 年 10 月 7 日發佈，以下是時間表：</p><ul><li>Beta 公測 – 2021 年 9 月 16 日</li><li>最終發佈 – 2021 年 10 月 7 日</li></ul><p>正如每個 Plasma 版本更新一樣，本次更新也同樣承諾對核心 Plasma Shell 和 KDE 應用進行大幅更改、代碼清理、性能改進、數百個 bug 修復、Wayland 優化等。我們在本篇文章中收集了一些重要的功能，讓你對即將發佈的新功能有基本瞭解。下面就讓我們看看。</p><h3 id="kde-plasma-5-23-–-新功能" tabindex="-1">KDE Plasma 5.23 – 新功能 <a class="header-anchor" href="#kde-plasma-5-23-–-新功能" aria-label="Permalink to “KDE Plasma 5.23 – 新功能”">​</a></h3><ul><li>本次版本更新基於 Qt 5.15 版本，KDE 框架 5.86 版本。</li></ul><h4 id="plasma-shell-和應用程序更新" tabindex="-1">Plasma Shell 和應用程序更新 <a class="header-anchor" href="#plasma-shell-和應用程序更新" aria-label="Permalink to “Plasma Shell 和應用程序更新”">​</a></h4><ul><li>本次 KDE Plasma 的 Kickoff 程序啓動器將有大幅更新，包括 bug 修復、減少內存佔用、視覺更新、鍵鼠導航優化。</li><li>Kickoff 程序啓動器菜單允許使用固定按鈕固定在桌面上，保持開啓狀態。</li><li>Kickoff 的標籤不會在你滾動時切換（從應用標籤到位置標籤）。</li><li>Kickoff 裏可以使用 <code>CTRL+F</code> 快捷鍵直接聚焦到搜索欄。</li><li>Kickoff 中的操作按鈕（如關機等）可以設置為僅顯示圖標。</li><li>現在可以針對所有 Kickoff 項目選擇使用網格或列表視圖（而不僅僅侷限於收藏夾）。</li></ul><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/New-Kickoff-Options-in-KDE-Plasma-5.23.jpeg" alt="KDE Plasma 5.23 中 Kickoff 程序啓動器新增的選項"></p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/Changes-in-kickoff.jpeg" alt="Kickoff 程序啓動器的更改"></p><ul><li>新增基於 QML 的全新概覽視圖（類似 GNOME 3.38 的工作區視圖），用於展示所有打開的窗口（詳見如下視頻）。目前我找不到關於此合併請求的更多詳情，而且這個新視圖也很不穩定。</li></ul><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/New-Overview-effect-in-KDE-Plasma-5.23.mp4" alt=""></p><p><em>視頻作者：KDE 團隊</em></p><ul><li>該概覽效果將替代現有的“展現窗口”特效和“虛擬桌面平鋪網格”特效（計劃中）。</li><li>未連接觸控板時將展示更易察覺的“未找到觸摸板”提示。</li><li>“電源配置方案”設置現在呈現於 Plasma UI（電池和亮度窗口）中。電源配置方案功能從 Linux 內核 5.12 版本開始已經登陸戴爾和聯想的筆記本電腦了。因此，如果你擁有這些品牌的較新款筆記本電腦，你可以將電源配置方案設置為高性能或省電模式。<em>[注：Fedora 35（很大可能）會在 GNOME 41 中增加該功能]</em></li></ul><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/New-power-profiles.jpeg" alt="新的“電源配置方案”設置"></p><ul><li>如果你有多屏幕設置，包括垂直和橫向屏幕，那麼登錄屏幕現在可以正確同步和對齊。這個功能的需求度很高。</li><li>新的 Breeze 主題預計會有風格上的更新。</li><li>如前序版本一樣，預計會有全新的壁紙（目前壁紙大賽仍在進行中）。</li><li>新增當硬件從筆記本模式切換到平板模式時是否縮放系統托盤圖標的設置。</li><li>你可以選擇在登錄時的藍牙狀態：總是啓用、總是禁用、記住上一次的狀態。該狀態在版本升級後仍可保留。</li><li>用户現在可以更改傳感器的顯示名稱。</li><li>Breeze 風格的滾動條現在比之前版本的更寬。</li><li>Dolphin 文件管理器提供在文件夾前之前優先顯示隱藏文件的新選項。</li><li>你現在可以使用 <code>DEL</code> 鍵刪除剪貼板彈窗中選中的項目。</li><li>KDE 現在允許你直接從 Plasma 桌面，向 store.kde.org 提交你製作的圖標和主題。</li></ul><h4 id="wayland-更新" tabindex="-1">Wayland 更新 <a class="header-anchor" href="#wayland-更新" aria-label="Permalink to “Wayland 更新”">​</a></h4><ul><li>在 Wayland 會話中，運行程序時光標旁也會展示圖標反饋動畫。</li><li>現在可以從通知中複製文字。</li><li>中鍵單擊粘貼功能現在可以在 Wayland 和 XWayland 應用程序中正常使用。</li></ul><p>請務必牢記，每個版本都有數以百計的 bug 修復和改進。本文僅僅包括了我收集的表面層次的東西。因此，如果想了解應用程序和 Plasma Shell 的變更詳情，請訪問 GitLab 或 KDE Planet 社區。</p><h3 id="不穩定版本下載" tabindex="-1">不穩定版本下載 <a class="header-anchor" href="#不穩定版本下載" aria-label="Permalink to “不穩定版本下載”">​</a></h3><p>你現在可以通過下方的鏈接下載 KDE neon 的不穩定版本來體驗上述全部功能。直接下載 .iso 文件，然後安裝測試即可。請務必在發現 bug 後及時反饋。該不穩定版本不適合嚴肅場合及生產力設備使用。</p>',21)),e("ul",null,[e("li",null,[i(t,{href:"https://neon.kde.org/download"},{default:s(()=>[...l[3]||(l[3]=[a("下載 KDE neon 不穩定版本",-1)])]),_:1})])]),l[23]||(l[23]=e("h3",{id:"結束語",tabindex:"-1"},[a("結束語 "),e("a",{class:"header-anchor",href:"#結束語","aria-label":"Permalink to “結束語”"},"​")],-1)),l[24]||(l[24]=e("p",null,"KDE Plasma 5.23 每次發佈都在改進底層、增加新功能。雖然這個版本不是大更新，但一切優化、改進最終都將累積成穩定性、適應性和更好的用户體驗。當然，還有更多的 Wayland 改進（講真，Wayland 兼容看上去一直都處在“正在進行中”的狀態 - 就像十年過去了，卻還在製作那樣。當然這是另一個話題了）。",-1)),l[25]||(l[25]=e("p",null,"再會。",-1)),l[26]||(l[26]=e("hr",null,null,-1)),e("p",null,[l[5]||(l[5]=a("via: ",-1)),i(t,{href:"https://www.debugpoint.com/2021/08/kde-plasma-5-23/"},{default:s(()=>[...l[4]||(l[4]=[a("https://www.debugpoint.com/2021/08/kde-plasma-5-23/",-1)])]),_:1})]),e("p",null,[l[10]||(l[10]=a("作者：",-1)),i(t,{href:"https://www.debugpoint.com/author/admin1/"},{default:s(()=>[...l[6]||(l[6]=[a("Arindam",-1)])]),_:1}),l[11]||(l[11]=a(" 選題：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...l[7]||(l[7]=[a("lujun9972",-1)])]),_:1}),l[12]||(l[12]=a(" 譯者：",-1)),i(t,{href:"https://github.com/imgradeone"},{default:s(()=>[...l[8]||(l[8]=[a("imgradeone",-1)])]),_:1}),l[13]||(l[13]=a(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:s(()=>[...l[9]||(l[9]=[a("wxy",-1)])]),_:1})]),e("p",null,[l[16]||(l[16]=a("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...l[14]||(l[14]=[a("LCTT",-1)])]),_:1}),l[17]||(l[17]=a(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:s(()=>[...l[15]||(l[15]=[a("Linux中國",-1)])]),_:1}),l[18]||(l[18]=a(" 榮譽推出",-1))])])}const k=n(d,[["render",u]]);export{b as __pageData,k as default};
